class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        max_sum = 150 * 12
        offset = max_sum
        # dp[s][p] stores the max product for alternating sum (s - offset) and next parity p
        # p=0: next element will be at even index (positive contribution)
        # p=1: next element will be at odd index (negative contribution)
        dp = [[-1] * 2 for _ in range(2 * max_sum + 1)]

        for x in nums:
            # Create a copy of current dp state to avoid using the same element multiple times in one step
            new_dp = [row[:] for row in dp]

            # Option 1: Start a new subsequence with x
            if x <= limit:
                s_new = x + offset
                if 0 <= s_new < len(dp):
                    # Next parity is 1 (odd index)
                    if x > new_dp[s_new][1]:
                        new_dp[s_new][1] = x

            # Option 2: Extend existing subsequences with x
            for s in range(len(dp)):
                for p in range(2):
                    prod = dp[s][p]
                    if prod == -1:
                        continue

                    # Calculate new sum and parity
                    if p == 0:
                        s_new = s + x
                    else:
                        s_new = s - x

                    p_new = 1 - p
                    prod_new = prod * x

                    if 0 <= s_new < len(dp) and prod_new <= limit:
                        if prod_new > new_dp[s_new][p_new]:
                            new_dp[s_new][p_new] = prod_new

            dp = new_dp

        # The answer is the max product for alternating sum k, regardless of the next parity
        idx = k + offset
        if 0 <= idx < len(dp):
            ans = max(dp[idx][0], dp[idx][1])
            return ans if ans != -1 else -1
        else:
            return -1

import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator))
        Y = int(next(iterator))
        S = next(iterator)
        T = next(iterator)
    except StopIteration:
        return

    # Count zeros in S and T
    zeros_S = []
    zeros_T = []

    for i in range(N):
        if S[i] == '0':
            zeros_S.append(i + 1) # 1-indexed position
        if T[i] == '0':
            zeros_T.append(i + 1) # 1-indexed position

    # Condition 1: Number of zeros must be equal
    if len(zeros_S) != len(zeros_T):
        print("No")
        return

    # Condition 2: Positions modulo gcd(X, Y) must match for corresponding zeros
    G = gcd(X, Y)

    for z_s, z_t in zip(zeros_S, zeros_T):
        if z_s % G != z_t % G:
            print("No")
            return

    print("Yes")

if __name__ == '__main__':
    solve()

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def get_perimeter_pos(p):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        # Map each point to (perimeter_pos, x, y)
        mapped = []
        for p in points:
            mapped.append((get_perimeter_pos(p), p[0], p[1]))

        # Sort by perimeter position
        mapped.sort(key=lambda x: x[0])

        n = len(mapped)
        perimeter = 4 * side

        # Check if it's possible to select k points with min Manhattan distance >= d
        def check(d):
            # Extended list to handle circular nature
            # We only need to consider starting from each of the original n points
            # and then greedily pick the next point that is at least d away in Manhattan distance

            # Precompute the extended list: original points + first n-1 points with perimeter + perimeter
            ext = mapped + [(mapped[i][0] + perimeter, mapped[i][1], mapped[i][2]) for i in range(n - 1)]

            for start in range(n):
                count = 1
                last_x, last_y = mapped[start][1], mapped[start][2]
                # Start searching from the next point after start in the extended list
                idx = start + 1
                while idx < len(ext) and count < k:
                    x, y = ext[idx][1], ext[idx][2]
                    # Manhattan distance
                    dist = abs(last_x - x) + abs(last_y - y)
                    if dist >= d:
                        count += 1
                        last_x, last_y = x, y
                    idx += 1
                if count >= k:
                    return True
            return False

        # Binary search for the maximum d
        lo, hi = 0, 4 * side
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if check(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        # Split p into prefix, middle, suffix
        parts = p.split('*')
        # There should be 3 parts because there are exactly two '*'
        prefix, middle, suffix = parts[0], parts[1], parts[2]

        len_prefix = len(prefix)
        len_middle = len(middle)
        len_suffix = len(suffix)

        # Precompute all prefix matches: list of start indices
        prefix_matches = []
        if len_prefix == 0:
            # Empty prefix matches at every position from 0 to n
            prefix_matches = list(range(n + 1))
        else:
            start = 0
            while start <= n - len_prefix:
                idx = s.find(prefix, start)
                if idx == -1:
                    break
                prefix_matches.append(idx)
                start = idx + 1

        # Precompute all suffix matches: list of start indices
        suffix_matches = []
        if len_suffix == 0:
            # Empty suffix matches at every position from 0 to n
            suffix_matches = list(range(n + 1))
        else:
            start = 0
            while start <= n - len_suffix:
                idx = s.find(suffix, start)
                if idx == -1:
                    break
                suffix_matches.append(idx)
                start = idx + 1

        # Precompute min_suf: min_suffix_start_after[i] = min start index of a suffix match that starts at or after i
        min_suf = [float('inf')] * (n + 2)  # extra space for safety
        for s1 in suffix_matches:
            if s1 <= n:
                min_suf[s1] = min(min_suf[s1], s1)
        # Backward pass
        for i in range(n - 1, -1, -1):
            min_suf[i] = min(min_suf[i], min_suf[i + 1])

        # Precompute max_pre: max_prefix_start_before[i] = max start index of a prefix match that ends at or before i
        max_pre = [-1] * (n + 2)
        for s0 in prefix_matches:
            e0 = s0 + len_prefix
            if e0 <= n:
                max_pre[e0] = max(max_pre[e0], s0)
        # Forward pass
        for i in range(1, n + 1):
            max_pre[i] = max(max_pre[i], max_pre[i - 1])

        ans = float('inf')

        if len_middle == 0:
            # For each prefix match, find the earliest suffix that starts at or after the prefix end
            for s0 in prefix_matches:
                e0 = s0 + len_prefix
                if e0 > n:
                    continue
                s1 = min_suf[e0]
                if s1 != float('inf'):
                    # The matched substring is from s0 to s1 + len_suffix
                    length = s1 + len_suffix - s0
                    ans = min(ans, length)
        else:
            # Find all occurrences of middle in s
            middle_matches = []
            start = 0
            while start <= n - len_middle:
                idx = s.find(middle, start)
                if idx == -1:
                    break
                middle_matches.append(idx)
                start = idx + 1

            for k in middle_matches:
                e_mid = k + len_middle
                if e_mid > n:
                    continue
                # Get the best prefix start that ends at or before k
                s0 = max_pre[k]
                if s0 == -1:
                    continue
                # Get the best suffix start that starts at or after e_mid
                s1 = min_suf[e_mid]
                if s1 == float('inf'):
                    continue
                length = s1 + len_suffix - s0
                ans = min(ans, length)

        return ans if ans != float('inf') else -1

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Build a segment tree for range max subarray sum queries
        # Each node stores: (max_sub, prefix_max, suffix_max, total_sum)
        size = 1
        while size < n:
            size *= 2

        # Initialize tree with identity values
        # For empty ranges, we use very small numbers for max_sub, prefix_max, suffix_max
        # and 0 for total_sum? Actually, for empty ranges, we should return a very small number.
        # But our queries will be on non-empty ranges only (since we skip empty segments).
        # We'll use a sentinel for "no valid subarray" which is -inf.
        INF = float('inf')

        tree = [None] * (2 * size)

        def merge(left, right):
            """Merge two nodes."""
            if left is None:
                return right
            if right is None:
                return left
            l_max_sub, l_prefix, l_suffix, l_total = left
            r_max_sub, r_prefix, r_suffix, r_total = right

            new_total = l_total + r_total
            new_prefix = max(l_prefix, l_total + r_prefix)
            new_suffix = max(r_suffix, r_total + l_suffix)
            new_max_sub = max(l_max_sub, r_max_sub, l_suffix + r_prefix)

            return (new_max_sub, new_prefix, new_suffix, new_total)

        # Build the tree
        # Leaves: for index i, the node is (nums[i], nums[i], nums[i], nums[i])
        for i in range(n):
            tree[size + i] = (nums[i], nums[i], nums[i], nums[i])
        for i in range(n, size):
            tree[size + i] = None  # empty

        for i in range(size - 1, 0, -1):
            tree[i] = merge(tree[2 * i], tree[2 * i + 1])

        def query(l, r):
            """Query max subarray sum in [l, r] (0-indexed, inclusive)."""
            if l > r:
                return None
            l += size
            r += size
            res_left = None
            res_right = None
            while l <= r:
                if l % 2 == 1:
                    res_left = merge(res_left, tree[l])
                    l += 1
                if r % 2 == 0:
                    res_right = merge(tree[r], res_right)
                    r -= 1
                l //= 2
                r //= 2
            return merge(res_left, res_right)

        # Original max subarray sum
        orig_result = query(0, n - 1)
        if orig_result is None:
            orig_result = -INF
        else:
            orig_result = orig_result[0]

        ans = orig_result

        # Group indices by value
        from collections import defaultdict
        pos = defaultdict(list)
        for i, x in enumerate(nums):
            pos[x].append(i)

        # For each unique x, compute max subarray sum after removing all x
        for x, indices in pos.items():
            # The segments are: [0, indices[0]-1], [indices[0]+1, indices[1]-1], ..., [indices[-1]+1, n-1]
            segments = []
            prev = -1
            for idx in indices:
                if prev + 1 <= idx - 1:
                    segments.append((prev + 1, idx - 1))
                prev = idx
            if prev + 1 <= n - 1:
                segments.append((prev + 1, n - 1))

            for l, r in segments:
                res = query(l, r)
                if res is not None:
                    ans = max(ans, res[0])

        return ans

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(L):
            # Check if it's possible to have max block length <= L with <= numOps flips
            flips_needed = 0
            i = 0
            while i < n:
                j = i
                # Find the end of the current block of identical characters
                while j < n and s[j] == s[i]:
                    j += 1
                block_len = j - i
                # Calculate flips needed for this block
                if block_len > L:
                    flips_needed += (block_len - 1) // L
                i = j
                # Early termination if flips exceed numOps
                if flips_needed > numOps:
                    return False
            return flips_needed <= numOps

        # Binary search on the answer L
        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Union-Find data structure
        parent = list(range(n))
        rank = [0] * n
        num_components = n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            nonlocal num_components
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            if rank[rx] == rank[ry]:
                rank[rx] += 1
            num_components -= 1

        # Map each number to its index
        val_to_idx = {val: i for i, val in enumerate(nums)}

        # For each number x in nums, iterate over multiples m = k*x up to threshold
        # If m is also in nums, then lcm(x, m) = m <= threshold, so they are connected.
        # This covers all pairs (a, b) where one divides the other.
        # But what about pairs where neither divides the other?
        # As discussed, if lcm(a, b) = L <= threshold, then both a and b divide L.
        # We can use the sieve-like approach: for each L from 1 to threshold,
        # find all numbers in nums that divide L, and union them.

        # Efficient approach:
        # Create a list of indices for each L from 1 to threshold.
        # nodes_at_L[L] will contain indices of numbers in nums that divide L.
        # We can build this by iterating over each x in nums and adding its index to all multiples of x up to threshold.

        nodes_at_L = [[] for _ in range(threshold + 1)]

        for val, idx in val_to_idx.items():
            if val > threshold:
                continue
            # Add idx to all multiples of val up to threshold
            for m in range(val, threshold + 1, val):
                nodes_at_L[m].append(idx)

        # Now, for each L, union all nodes that divide L
        for L in range(1, threshold + 1):
            nodes = nodes_at_L[L]
            if len(nodes) > 1:
                first = nodes[0]
                for i in range(1, len(nodes)):
                    union(first, nodes[i])

        return num_components
